-- ============================================================
-- AIECG database schema + seed data (PostgreSQL 15+ / Supabase)
-- Generated from the live project. Run on a fresh database:
--   psql "$DATABASE_URL" -f aiecg-schema.sql
-- ============================================================

BEGIN;

-- ------------------------------------------------------------ User
CREATE TABLE IF NOT EXISTS "User" (
  "id" text NOT NULL,
  "email" text NOT NULL,
  "passwordHash" text NOT NULL,
  "doctorName" text NOT NULL,
  "hospitalName" text NOT NULL,
  "specialty" text,
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp(3) NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "User_email_key" UNIQUE ("email")
);


-- ------------------------------------------------------------ Session
CREATE TABLE IF NOT EXISTS "Session" (
  "id" text NOT NULL,
  "token" text NOT NULL,
  "userId" text NOT NULL,
  "expiresAt" timestamp(3) NOT NULL,
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "Session_token_key" UNIQUE ("token")
);

CREATE INDEX IF NOT EXISTS "Session_userId_idx" ON "Session" ("userId");

-- ------------------------------------------------------------ EcgCase
CREATE TABLE IF NOT EXISTS "EcgCase" (
  "id" text NOT NULL,
  "caseNumber" text NOT NULL,
  "userId" text NOT NULL,
  "patientName" text NOT NULL,
  "patientAge" INTEGER NOT NULL,
  "patientGender" text NOT NULL,
  "patientId" text,
  "bloodPressure" text,
  "clinicalNotes" text,
  "imageBase64" text NOT NULL,
  "imageMimeType" text NOT NULL,
  "status" text NOT NULL DEFAULT 'analyzing',
  "error" text,
  "heartRate" INTEGER,
  "rhythm" text,
  "pWave" text,
  "prInterval" text,
  "qrsDuration" text,
  "qtInterval" text,
  "qtcInterval" text,
  "axis" text,
  "stSegment" text,
  "quality" text,
  "confidence" text,
  "normality" text,
  "urgency" text,
  "findingsJson" text,
  "conclusion" text,
  "recommendationsJson" text,
  "leadFindingsJson" text,
  "regionalSummaryJson" text,
  "crossCheckJson" text,
  "digitizedAt" timestamp(3),
  "digitizerInfo" text,
  "signalsJson" text,
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp(3) NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "EcgCase_caseNumber_key" UNIQUE ("caseNumber")
);

CREATE INDEX IF NOT EXISTS "EcgCase_userId_createdAt_idx" ON "EcgCase" ("userId", "createdAt");
CREATE INDEX IF NOT EXISTS "EcgCase_status_idx" ON "EcgCase" ("status");

-- ------------------------------------------------------------ ChatMessage
CREATE TABLE IF NOT EXISTS "ChatMessage" (
  "id" text NOT NULL,
  "caseId" text NOT NULL,
  "role" text NOT NULL,
  "content" text NOT NULL,
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "ChatMessage_caseId_createdAt_idx" ON "ChatMessage" ("caseId", "createdAt");

-- ------------------------------------------------------------ DoctorFeedback
CREATE TABLE IF NOT EXISTS "DoctorFeedback" (
  "id" text NOT NULL,
  "caseId" text NOT NULL,
  "userId" text NOT NULL,
  "verdict" text NOT NULL,
  "correctNormality" text,
  "correctUrgency" text,
  "comment" text,
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "DoctorFeedback_caseId_userId_key" UNIQUE ("caseId", "userId")
);

CREATE INDEX IF NOT EXISTS "DoctorFeedback_userId_createdAt_idx" ON "DoctorFeedback" ("userId", "createdAt");

-- ------------------------------------------------------------ ScpCode
CREATE TABLE IF NOT EXISTS "ScpCode" (
  "id" text NOT NULL,
  "label" text NOT NULL,
  "diagnosticClass" text,
  "isDiagnostic" BOOLEAN NOT NULL DEFAULT false,
  "isForm" BOOLEAN NOT NULL DEFAULT false,
  "isRhythm" BOOLEAN NOT NULL DEFAULT false,
  "ahaCode" text,
  "dicomCode" text,
  "category" text,
  "description" text,
  "sourceDataset" text NOT NULL DEFAULT 'PTB-XL v1.0.3',
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" timestamp(3) NOT NULL,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "ScpCode_diagnosticClass_idx" ON "ScpCode" ("diagnosticClass");

-- ------------------------------------------------------------ LeadCriterion
CREATE TABLE IF NOT EXISTS "LeadCriterion" (
  "id" text NOT NULL,
  "lead" text NOT NULL,
  "region" text NOT NULL,
  "criterion" text NOT NULL,
  "detail" text NOT NULL,
  "source" text NOT NULL DEFAULT 'PTB-XL / standard 12-lead criteria',
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "LeadCriterion_lead_criterion_key" UNIQUE ("lead", "criterion"),
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "LeadCriterion_region_idx" ON "LeadCriterion" ("region");

-- ------------------------------------------------------------ ReferenceEcg
CREATE TABLE IF NOT EXISTS "ReferenceEcg" (
  "id" text NOT NULL,
  "sourceDataset" text NOT NULL DEFAULT 'PTB-XL',
  "sourceRecord" text NOT NULL,
  "sourceLabel" text NOT NULL,
  "superclass" text NOT NULL,
  "samplingHz" INTEGER NOT NULL DEFAULT 100,
  "durationS" DOUBLE PRECISION NOT NULL DEFAULT 10.0,
  "signalsJson" text NOT NULL,
  "metaJson" text,
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "ReferenceEcg_sourceDataset_sourceRecord_key" UNIQUE ("sourceDataset", "sourceRecord")
);

CREATE INDEX IF NOT EXISTS "ReferenceEcg_superclass_idx" ON "ReferenceEcg" ("superclass");

-- ------------------------------------------------------------ ModelVersion
CREATE TABLE IF NOT EXISTS "ModelVersion" (
  "id" text NOT NULL,
  "version" INTEGER NOT NULL,
  "architecture" text NOT NULL,
  "basePath" text NOT NULL,
  "scalerJson" text NOT NULL,
  "metricsJson" text,
  "trainRecords" INTEGER NOT NULL DEFAULT 0,
  "sourceNote" text,
  "isActive" BOOLEAN NOT NULL DEFAULT false,
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id"),
  CONSTRAINT "ModelVersion_version_key" UNIQUE ("version")
);

CREATE INDEX IF NOT EXISTS "ModelVersion_isActive_idx" ON "ModelVersion" ("isActive");

-- ------------------------------------------------------------ LearningSample
CREATE TABLE IF NOT EXISTS "LearningSample" (
  "id" text NOT NULL,
  "caseId" text,
  "source" text NOT NULL,
  "labelNormality" text NOT NULL,
  "superclass" text NOT NULL,
  "signalsJson" text NOT NULL,
  "samplingHz" INTEGER NOT NULL DEFAULT 100,
  "metaJson" text,
  "labelOrigin" text NOT NULL,
  "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "LearningSample_superclass_idx" ON "LearningSample" ("superclass");
CREATE INDEX IF NOT EXISTS "LearningSample_source_createdAt_idx" ON "LearningSample" ("source", "createdAt");

-- ------------------------------------------------------------ LearningRun
CREATE TABLE IF NOT EXISTS "LearningRun" (
  "id" text NOT NULL,
  "startedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "finishedAt" timestamp(3),
  "status" text NOT NULL DEFAULT 'running',
  "trigger" text NOT NULL DEFAULT 'manual',
  "samplesUsed" INTEGER NOT NULL DEFAULT 0,
  "referencesUsed" INTEGER NOT NULL DEFAULT 0,
  "newVersionId" text,
  "metricsJson" text,
  "logJson" text,
  "error" text,
  PRIMARY KEY ("id")
);

CREATE INDEX IF NOT EXISTS "LearningRun_startedAt_idx" ON "LearningRun" ("startedAt");

-- ============================================================
-- SEED DATA (knowledge base + model registry + learning runs)
